<template>
  <main class="referee-workbench" v-loading="loading">
    <header v-if="tournament" class="event-context">
      <div class="event-main">
        <span class="event-mark"><el-icon><Trophy /></el-icon></span>
        <strong>{{ tournament.name || tournament.tournamentName }}</strong>
        <el-tag effect="plain" type="primary">{{ divisionCount }} 个组别</el-tag>
        <el-tag effect="plain" type="success">进行中</el-tag>
        <span><el-icon><Calendar /></el-icon>{{ eventDates }}</span>
        <span><el-icon><Location /></el-icon>{{ tournament.province || tournament.location || '举办地待定' }}</span>
      </div>
      <el-button plain @click="router.push('/tournament-space')"><el-icon><SwitchButton /></el-icon>退出赛事空间</el-button>
    </header>

    <section class="work-area">
      <div class="title-row">
        <div><h1>裁判管理</h1></div>
        <div class="title-actions"><el-button type="warning" plain @click="addDialog = true"><el-icon><Plus /></el-icon>添加临时裁判</el-button><el-button v-if="!isTournamentStaff" plain type="warning" @click="openSyntheticPool">导入虚拟裁判资料</el-button><el-button plain type="success" @click="exportList"><el-icon><Download /></el-icon>导出裁判名单</el-button><el-button type="success" @click="openRefereeInvite()"><el-icon><Plus /></el-icon>邀请持证裁判</el-button></div>
      </div>

      <el-alert class="qualification-note" type="success" :closable="false" show-icon title="仅通过资格审核且处于可用状态的裁判，可被指派至赛事场次。" />

      <section class="stats">
        <article><el-icon><UserFilled /></el-icon><div>全部裁判<strong>{{ referees.length }}</strong></div></article>
        <article><el-icon><Aim /></el-icon><div>可执裁<strong>{{ availableCount }}</strong></div></article>
        <article><el-icon><Calendar /></el-icon><div>已指派场次<strong>{{ assignedMatchCount }}</strong></div></article>
        <article class="pending"><el-icon><DocumentChecked /></el-icon><div>待审核<strong>{{ pendingCount }}</strong></div></article>
      </section>

      <section class="toolbar">
        <el-radio-group v-model="statusFilter"><el-radio-button label="all">全部　{{ referees.length }}</el-radio-button><el-radio-button label="available">可执裁　{{ availableCount }}</el-radio-button><el-radio-button label="assigned">已指派　{{ assignedCount }}</el-radio-button><el-radio-button label="pending">待审核　{{ pendingCount }}</el-radio-button></el-radio-group>
        <el-select v-model="levelFilter" clearable placeholder="裁判等级"><el-option v-for="level in levels" :key="level" :label="level" :value="level" /></el-select>
        <el-select v-model="availabilityFilter" clearable placeholder="可用状态"><el-option label="可执裁" value="available" /><el-option label="已指派" value="assigned" /><el-option label="待审核" value="pending" /></el-select>
        <el-input v-model="keyword" clearable placeholder="搜索姓名或手机号"><template #prefix><el-icon><Search /></el-icon></template></el-input>
        <el-button plain type="success" @click="openBatch"><el-icon><Calendar /></el-icon>批量指派赛事</el-button>
      </section>

      <section class="table-panel">
        <table><thead><tr><th></th><th>裁判</th><th>等级 / 资格</th><th>可用时间</th><th>本届执裁</th><th>当前状态</th><th>已指派赛事</th><th>操作</th></tr></thead>
          <tbody><tr v-for="referee in filteredReferees" :key="referee._id">
            <td><el-checkbox :model-value="selectedIds.includes(referee._id)" @change="toggleSelected(referee._id, $event)" /></td>
            <td><div class="person"><el-avatar shape="square" :src="referee.avatarUrl"><el-icon><UserFilled /></el-icon></el-avatar><span><strong>{{ referee.name || referee.realName }}</strong><small>{{ referee.refereeGroupName || maskPhone(referee.phone || referee.phoneNumber) }}</small><small v-if="referee.temporaryReferee" class="temporary-label">赛事临时裁判</small></span></div></td>
            <td><strong>{{ referee.temporaryReferee ? '未提交裁判证' : (referee.level || referee.refereeLevel || '未定级') }}</strong><small>{{ referee.temporaryReferee ? '组委会添加 · 仅限本赛事' : (referee.qualification || referee.certificateName || '资格资料待补充') }}</small><small v-if="referee.groupRoleLabel">{{ referee.groupRoleLabel }}</small></td>
            <td><span>{{ tournament?.startDate || '未设置' }}</span><small>～ {{ tournament?.endDate || '未设置' }}</small></td>
            <td>{{ assignmentCount(referee) }} 场</td><td><span class="state" :class="stateOf(referee)"><i />{{ stateLabel(stateOf(referee)) }}</span></td><td>{{ assignmentCount(referee) }} 场比赛</td>
            <td class="row-actions"><el-button @click="showProfile(referee)">查看资料</el-button><el-button v-if="stateOf(referee) === 'pending_claim'" type="warning" plain @click="openRefereeInvite(referee)">重新发送认领</el-button><el-button v-else-if="stateOf(referee) === 'pending_temporary_review'" type="warning" plain @click="approve(referee)">确认临时执裁</el-button><span v-else-if="stateOf(referee) === 'pending' && isTournamentStaff">资格待审核</span><el-button v-else-if="stateOf(referee) === 'pending'" type="warning" plain @click="approve(referee)">审核资格</el-button><el-button v-else-if="stateOf(referee) === 'test'" type="warning" plain @click="openRefereeInvite(referee)">邀请扫码绑定</el-button><el-button v-else type="success" plain @click="openAssign(referee)">指派场次</el-button></td>
          </tr></tbody>
        </table>
      </section>
      <el-alert class="bottom-note" type="success" :closable="false" show-icon title="赛事指派后，裁判将在移动端收到待执行场次；临近开赛时支持替补裁判调度。" />
    </section>

    <div v-if="assignDialog || route.query.assignment" class="modal-mask" @click.self="closeAssign"><section class="work-modal assignment-modal"><header><strong>{{ batchMode ? '批量指派赛事' : '指派裁判场次' }}</strong><button type="button" aria-label="关闭" @click="closeAssign">×</button></header><p class="modal-hint">请选择同一赛制的场次并完整安排四人裁判组；虚拟裁判仅用于排班测试，已锁定电子记录的场次不会被覆盖。</p><div class="match-pick-list"><label v-for="match in assignableMatches" :key="match._id" :class="{ locked: match.refereeRecordLocked }"><input v-model="selectedMatches" type="checkbox" :value="match" :disabled="match.refereeRecordLocked" /><span><strong>{{ match.matchSequence }}</strong>　{{ match.homeTeamName || '待定' }} vs {{ match.awayTeamName || '待定' }}</span><small>{{ match.matchDate }} {{ match.matchTime }} · {{ match.refereeRecordLocked ? '记录已锁定' : '可指派' }}</small></label></div><div class="assign-form"><label v-for="role in roles" :key="role.key">{{ role.label }}<el-select v-model="crew[role.key]" filterable clearable :placeholder="`请选择${role.label}`"><el-option v-for="referee in approvedReferees" :key="referee._id" :label="`${referee.name || referee.realName} · ${referee.level || referee.refereeLevel || '未定级'}${referee.synthetic ? ' · 虚拟测试' : ''}`" :value="referee._id" /></el-select></label></div><footer><el-button @click="closeAssign">取消</el-button><el-button type="success" :loading="saving" @click="saveAssignment">确认指派</el-button></footer></section></div>
    <div v-if="profileDialog" class="modal-mask" @click.self="profileDialog = false"><section class="work-modal referee-profile-modal"><header><strong>裁判资料</strong><button type="button" aria-label="关闭" @click="profileDialog = false">×</button></header><div class="profile-media" v-loading="profileLoading"><figure><figcaption>裁判二寸照</figcaption><img v-if="profileAvatarUrl" :src="profileAvatarUrl" alt="裁判二寸照" /><div v-else class="profile-media-empty"><el-icon><UserFilled /></el-icon><span>暂无头像</span></div></figure><figure><figcaption>裁判证原图</figcaption><img v-if="profileCertificateUrl" :src="profileCertificateUrl" alt="裁判证原图" /><div v-else class="profile-media-empty"><el-icon><DocumentChecked /></el-icon><span>暂无证书图片</span></div><a v-if="profileCertificateUrl" :href="profileCertificateUrl" target="_blank" rel="noopener">查看原图</a></figure></div><dl><dt>姓名</dt><dd>{{ activeReferee.name || activeReferee.realName }}</dd><dt>手机</dt><dd>{{ activeReferee.phone || activeReferee.phoneNumber || '未填写' }}</dd><dt>裁判等级</dt><dd>{{ activeReferee.level || activeReferee.refereeLevel || '未定级' }}</dd><dt>证书编号</dt><dd>{{ activeReferee.certificateNumber || activeReferee.qualification || '待补充' }}</dd><dt>发证机关</dt><dd>{{ activeReferee.issuingAuthority || '待补充' }}</dd><dt>发证日期</dt><dd>{{ activeReferee.certificateIssueDate || '待补充' }}</dd><template v-if="activeReferee.certificateRisks?.length"><dt>证书风险提示</dt><dd class="risk-copy">{{ activeReferee.certificateRisks.map(item => item.label).join('、') }}（仅供人工复核）</dd></template></dl></section></div>
    <div v-if="addDialog" class="modal-mask" @click.self="addDialog = false"><section class="work-modal compact-modal"><header><strong>添加临时裁判</strong><button type="button" aria-label="关闭" @click="addDialog = false">×</button></header><div class="add-form"><label>姓名<el-input v-model="newReferee.name" maxlength="40" /></label><label>手机号<el-input v-model="newReferee.phone" maxlength="11" /></label><label class="full-field">添加原因<el-input v-model="newReferee.reason" type="textarea" :rows="3" maxlength="200" show-word-limit /></label></div><footer><el-button @click="addDialog = false">取消</el-button><el-button type="warning" :loading="saving" @click="createTemporaryReferee">添加并通知认领</el-button></footer></section></div>
    <div v-if="syntheticPoolVisible" class="modal-mask" @click.self="syntheticPoolVisible = false"><section class="work-modal synthetic-pool-modal"><header><strong>模拟裁判资料库（30人）</strong><button type="button" aria-label="关闭" @click="syntheticPoolVisible = false">×</button></header><p class="modal-hint">这里是虚构测试资料，不会批量加入裁判名单。请逐个选择；添加后可以直接用于赛程排班测试，但不能登录、接收通知或执行真实执裁任务。</p><div class="synthetic-grid"><article v-for="candidate in syntheticCandidates" :key="candidate.key"><img :src="candidate.avatarUrl" :alt="`${candidate.name}模拟头像`" /><div><strong>{{ candidate.name }}</strong><small>{{ candidate.level }} · {{ candidate.refereeGroupName }}</small><small>{{ candidate.groupRoleLabel }}</small></div><el-button v-if="addedSyntheticKeys.has(candidate.key)" disabled>已添加</el-button><el-button v-else type="warning" plain :loading="addingSyntheticKey === candidate.key" @click="addSyntheticCandidate(candidate)">添加此人</el-button></article></div><footer><span>已添加 {{ addedSyntheticKeys.size }} / 30 人</span><el-button type="success" @click="syntheticPoolVisible = false">完成</el-button></footer></section></div>
    <div v-if="inviteDialog" class="modal-mask" @click.self="inviteDialog = false"><section class="work-modal compact-modal referee-invite-modal"><header><strong>{{ inviteTarget ? `邀请 ${inviteTarget.name || inviteTarget.realName} 认领` : '邀请持证裁判登记' }}</strong><button type="button" aria-label="关闭" @click="inviteDialog = false">×</button></header><div class="referee-invite-body"><img v-if="inviteQrCode" :src="inviteQrCode" alt="赛小蜂足球助手裁判关注二维码" /><h3>先关注服务号，再完成{{ inviteMode === 'temporary_no_certificate' ? '身份认领' : '裁判登记' }}</h3><ol v-if="inviteMode === 'temporary_no_certificate'"><li>使用组委会登记手机号验证</li><li>上传本人头像并提交认领</li><li>等待组委会确认临时执裁资格</li></ol><ol v-else><li>微信扫码关注“赛小蜂足球助手”</li><li>在服务号消息中进入裁判登记</li><li>上传裁判证和二寸照等待审核</li></ol><p>{{ inviteMode === 'temporary_no_certificate' ? '未绑定服务号时，请将二维码发给本人；临时资格仅限本届赛事。' : '后续比赛指派、时间调整和临场变更将通过同一服务号通知。' }}</p></div><footer><el-button type="success" @click="inviteDialog = false">完成</el-button></footer></section></div>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Aim, Calendar, DocumentChecked, Download, Location, Plus, Search, SwitchButton, Trophy, UserFilled } from '@element-plus/icons-vue'
import { addRecord, callFunction, getFileUrl, queryList, updateRecord } from '../../utils/cloud'
import { getVisualQaSnapshot, visualQaActive } from '../../utils/visualQaFixtures'

const route = useRoute(), router = useRouter()
const isTournamentStaff = sessionStorage.getItem('sxfTournamentStaff') === '1'
const previewMode=import.meta.env.BASE_URL.includes('/preview/')
const qaSnapshot = import.meta.env.DEV && visualQaActive() ? getVisualQaSnapshot() : null
const tournaments = ref(qaSnapshot?.tournament ? [qaSnapshot.tournament] : []), referees = ref(qaSnapshot?.referees || []), matches = ref(qaSnapshot?.matches || []), selectedTournamentId = ref(String(route.query.tournamentId || qaSnapshot?.tournament?._id || ''))
const loading = ref(false), saving = ref(false), keyword = ref(''), statusFilter = ref('all'), levelFilter = ref(''), availabilityFilter = ref('')
const selectedIds = ref([]), selectedMatches = ref([]), assignDialog = ref(false), profileDialog = ref(false), addDialog = ref(false), batchMode = ref(false), activeReferee = ref({})
const inviteDialog=ref(false),inviteQrCode=ref(''),inviteTarget=ref(null),inviteMode=ref(''),syntheticPoolVisible=ref(false),addingSyntheticKey=ref('')
const profileLoading=ref(false),profileAvatarUrl=ref(''),profileCertificateUrl=ref('')
const crew = ref({ mainReferee: '', assistant1: '', assistant2: '', fourthOfficial: '' }), newReferee = ref({ name: '', phone: '', reason: '' })
const levels = ['国家级', '国家一级', '国家二级', '一级', '二级', '三级']
const roles = [{ key: 'mainReferee', label: '主裁判' }, { key: 'assistant1', label: '第一助理裁判' }, { key: 'assistant2', label: '第二助理裁判' }, { key: 'fourthOfficial', label: '第四官员' }]
const syntheticDatasetId='football-referee-candidate-pool-30-v2'
const syntheticNames=['林泽宇','周明远','陈思宁','赵启航','韩若溪','许嘉树','郑安然','何俊峰','宋雨桐','唐文博','冯知夏','曹景行','梁舒雅','邓子昂','叶清和','潘语晨','蒋毅然','袁静姝','程浩然','罗星语','顾承志','马晓岚','谢嘉诚','薛婉宁','方峻熙','董思齐','苏沐阳','石雅雯','孟致远','乔欣悦']
const roleLabels=['主裁判','第一助理裁判','第二助理裁判','第四官员','替补裁判']
const roleKeys=['mainReferee','assistant1','assistant2','fourthOfficial','reserveReferee']
const syntheticCandidates=syntheticNames.map((name,index)=>({key:`${syntheticDatasetId}:candidate-${index+1}`,name,avatarUrl:`${import.meta.env.BASE_URL}assets/synthetic-referees/referee-${String(index+1).padStart(2,'0')}.webp`,level:index%5===0?'国家二级':index%3===0?'二级':'一级',qualification:'模拟裁判测试资料（需真人扫码补充真实资格）',refereeGroupId:`virtual-group-${Math.floor(index/5)+1}`,refereeGroupName:`建议第${Math.floor(index/5)+1}裁判组`,groupRole:roleKeys[index%5],groupRoleLabel:roleLabels[index%5]}))
const tournament = computed(() => tournaments.value.find(item => item._id === selectedTournamentId.value) || tournaments.value[0] || null)
const divisionCount = computed(() => tournament.value?.divisions?.length || 1)
const eventDates = computed(() => [tournament.value?.startDate, tournament.value?.endDate].filter(Boolean).join('—') || '日期待定')
const assignedRefereeIds = computed(() => new Set(matches.value.flatMap(match => Object.values(match.refereeCrew || {}).map(person => typeof person === 'string' ? person : person?._id)).filter(Boolean)))
const stateOf = referee => {
  if (referee.synthetic === true) return 'virtual'
  if (referee.temporaryReferee === true) {
    if (referee.temporaryClaimStatus === 'waiting_claim' || referee.status === 'pending_claim') return 'pending_claim'
    if (referee.temporaryClaimStatus === 'claimed_pending_review') return 'pending_temporary_review'
    if (referee.temporaryClaimStatus === 'approved' && referee.organizerTemporaryApproval === true) return assignedRefereeIds.value.has(referee._id) ? 'assigned' : 'available'
    return 'pending'
  }
  if (referee.status === 'pending' || referee.auditStatus === 'pending') return 'pending'
  if (referee.canOperate === false) return 'test'
  return assignedRefereeIds.value.has(referee._id) ? 'assigned' : (referee.availabilityStatus || 'available')
}
const stateLabel = state => ({ available: '可执裁', assigned: '已指派', pending: '待审核',pending_claim:'待认领',pending_temporary_review:'待组委会确认',test:'待绑定',virtual:'虚拟可指派' })[state] || state
const assignmentCount = referee => matches.value.filter(match => Object.values(match.refereeCrew || {}).some(person => (typeof person === 'string' ? person : person?._id) === referee._id)).length
const availableCount = computed(() => referees.value.filter(item => stateOf(item) === 'available').length)
const assignedCount = computed(() => referees.value.filter(item => stateOf(item) === 'assigned').length)
const pendingCount = computed(() => referees.value.filter(item => ['pending','pending_claim','pending_temporary_review'].includes(stateOf(item))).length)
const assignedMatchCount = computed(() => matches.value.filter(match => Object.keys(match.refereeCrew || {}).length > 0).length)
const approvedReferees = computed(() => referees.value.filter(item => item.synthetic===true || (item.status==='approved' && item.canOperate!==false && (item.temporaryReferee!==true || (item.temporaryClaimStatus==='approved' && item.organizerTemporaryApproval===true && item.tournamentId===selectedTournamentId.value)))))
const addedSyntheticKeys=computed(()=>new Set(referees.value.filter(item=>item.tournamentId===selectedTournamentId.value && item.syntheticDatasetId===syntheticDatasetId).map(item=>item.syntheticKey)))
const assignableMatches = computed(() => matches.value.filter(match => !['finished', 'completed', 'cancelled'].includes(match.status)))
const filteredReferees = computed(() => referees.value.filter(item => { const state = stateOf(item); const text = `${item.name || item.realName || ''}${item.phone || item.phoneNumber || ''}`; const statusMatched=statusFilter.value === 'all' || state === statusFilter.value || (statusFilter.value==='pending'&&['pending_claim','pending_temporary_review'].includes(state)); const availabilityMatched=!availabilityFilter.value || state === availabilityFilter.value || (availabilityFilter.value==='pending'&&['pending_claim','pending_temporary_review'].includes(state)); return statusMatched && availabilityMatched && (!levelFilter.value || (item.level || item.refereeLevel) === levelFilter.value) && (!keyword.value || text.includes(keyword.value.trim())) }))
function maskPhone(phone) { const value = String(phone || ''); return value.length === 11 ? `${value.slice(0, 3)}****${value.slice(-4)}` : value || '未填写' }
function toggleSelected(id, checked) { selectedIds.value = checked ? [...new Set([...selectedIds.value, id])] : selectedIds.value.filter(item => item !== id) }
async function resolveProfileFile(value){const source=String(value||'').trim();if(!source)return '';if(source.startsWith('data:image/')||source.startsWith('http://')||source.startsWith('https://'))return source;const resolved=await getFileUrl(source);return /^https?:\/\//.test(String(resolved||''))?resolved:''}
async function showProfile(referee) { activeReferee.value = referee; profileAvatarUrl.value='';profileCertificateUrl.value='';profileDialog.value = true;profileLoading.value=true;try{const [avatar,certificate]=await Promise.all([resolveProfileFile(referee.avatarFileId||referee.avatarFileID||referee.avatarUrl),resolveProfileFile(referee.certificateFileId||referee.certificateFileID||referee.certificateUrl)]);profileAvatarUrl.value=avatar;profileCertificateUrl.value=certificate}catch(error){ElMessage.warning(error.message||'裁判图片暂时无法加载')}finally{profileLoading.value=false} }
function openAssign(referee) { batchMode.value = false; selectedMatches.value = []; crew.value = { mainReferee: referee._id, assistant1: '', assistant2: '', fourthOfficial: '' }; assignDialog.value = true; router.replace({ query: { ...route.query, assignment: referee._id } }) }
function openBatch() { const selected = approvedReferees.value.filter(item => selectedIds.value.includes(item._id)); if (!selected.length) return ElMessage.warning('请勾选已审核裁判或虚拟裁判'); batchMode.value = true; selectedMatches.value = []; crew.value = { mainReferee: selected[0]?._id || '', assistant1: selected[1]?._id || '', assistant2: selected[2]?._id || '', fourthOfficial: selected[3]?._id || '' }; assignDialog.value = true; router.replace({ query: { ...route.query, assignment: 'batch' } }) }
  async function closeAssign() { assignDialog.value = false; const { assignment, ...query } = route.query; await router.replace({ query }) }
async function load() { if (qaSnapshot) return; loading.value = true; try { const [events, people] = await Promise.all([queryList('tournaments', { orderBy: { createTime: 'desc' }, limit: 100 }), queryList('referees', { orderBy: { createTime: 'desc' }, limit: 500 })]); tournaments.value = events || []; if (!selectedTournamentId.value) selectedTournamentId.value = tournaments.value[0]?._id || ''; matches.value = selectedTournamentId.value ? await queryList('matches', { where: { tournamentId: selectedTournamentId.value }, orderBy: { matchDate: 'asc', matchTime: 'asc' }, limit: 500 }) : []; referees.value = people || [] } finally { loading.value = false } }
  async function saveAssignment() { if (!selectedMatches.value.length) return ElMessage.warning('请选择需要指派的场次'); if (!crew.value.mainReferee) return ElMessage.warning('请至少指定主裁判'); saving.value = true; try { const selected = Object.fromEntries(Object.entries(crew.value).filter(([, id]) => id).map(([role, id]) => { const referee = referees.value.find(item => item._id === id); return [role, { _id: id, name: referee?.name || referee?.realName || '' }] })); for (const match of selectedMatches.value) await callFunction('updateMatch', { matchId: match._id, data: { tournamentId: selectedTournamentId.value, refereeCrew: selected } }); await load(); await closeAssign(); ElMessage.success('裁判指派已保存') } catch (error) { ElMessage.error(error.message || '指派保存失败') } finally { saving.value = false } }
async function approve(referee) { if(referee.temporaryReferee){saving.value=true;try{const result=await callFunction('tournamentRegistrationFlow',{action:'reviewTemporaryRefereeClaim',refereeId:referee._id});if(!result?.success)throw new Error(result?.message||result?.error||'确认失败');await load();ElMessage.success('临时裁判已确认，仅可参与本赛事排班')}catch(error){ElMessage.error(error.message||'确认失败')}finally{saving.value=false}return}if(referee.certificateRisks?.length&&!window.confirm(`系统提示证书可能存在：${referee.certificateRisks.map(item=>item.label).join('、')}。该提示不能作为唯一审核依据，请确认您已人工查看证书原图。`))return;saving.value = true; try { await updateRecord('referees', referee._id, { status: 'approved', auditStatus: 'approved', availabilityStatus:'available', canOperate:true, certificateRiskReviewed:true }); await load(); ElMessage.success('资格审核已通过，可以参与执裁指派') } catch (error) { ElMessage.error(error.message || '审核失败') } finally { saving.value = false } }
async function createTemporaryReferee(){const name=newReferee.value.name.trim(),phone=newReferee.value.phone.replace(/\D/g,''),reason=newReferee.value.reason.trim();if(name.length<2)return ElMessage.warning('请填写裁判姓名');if(!/^1[3-9]\d{9}$/.test(phone))return ElMessage.warning('请填写正确的手机号');if(reason.length<4)return ElMessage.warning('请填写组委会添加原因');saving.value=true;try{const result=await callFunction('tournamentRegistrationFlow',{action:'createTemporaryRefereeClaim',tournamentId:selectedTournamentId.value,name,phone,reason,previewMode});if(!result?.success)throw new Error(result?.message||result?.error||'添加失败');inviteTarget.value={_id:result.data?.refereeId,name,phone,temporaryReferee:true};inviteMode.value='temporary_no_certificate';inviteQrCode.value=result.data?.qrCodeUrl||'';newReferee.value={name:'',phone:'',reason:''};addDialog.value=false;inviteDialog.value=true;await load();ElMessage.success('临时裁判已添加，认领通知已进入发送队列')}catch(error){ElMessage.error(error.message||'添加失败')}finally{saving.value=false}}
function openSyntheticPool(){if(!selectedTournamentId.value)return ElMessage.warning('请先选择赛事');syntheticPoolVisible.value=true}
async function addSyntheticCandidate(candidate){if(addedSyntheticKeys.value.has(candidate.key))return;addingSyntheticKey.value=candidate.key;try{await addRecord('referees',{tournamentId:selectedTournamentId.value,name:candidate.name,realName:candidate.name,avatarUrl:candidate.avatarUrl,level:candidate.level,qualification:candidate.qualification,status:'test',auditStatus:'not_bound',availabilityStatus:'available',refereeGroupId:candidate.refereeGroupId,refereeGroupName:candidate.refereeGroupName,groupRole:candidate.groupRole,groupRoleLabel:candidate.groupRoleLabel,synthetic:true,syntheticDatasetId,syntheticKey:candidate.key,source:'ai_candidate_pool',canLogin:false,canOperate:false,notificationDisabled:true});await load();ElMessage.success(`${candidate.name}已加入名单，可以直接用于排班测试`)}catch(error){ElMessage.error(error.message||'添加模拟裁判失败')}finally{addingSyntheticKey.value=''}}
function friendlyInviteError(error){const message=String(error?.message||error||'');if(/collection.+not exists|Db or Table not exist|ResourceNotFound|DATABASE_COLLECTION_NOT_EXIST/i.test(message))return '裁判邀请功能正在初始化，请刷新页面后重试';if(/permission|auth|unauthorized/i.test(message))return '当前账号没有创建裁判邀请的权限';return '裁判邀请生成失败，请稍后重试'}
async function openRefereeInvite(referee=null){if(!selectedTournamentId.value)return ElMessage.warning('请先选择赛事');saving.value=true;inviteTarget.value=referee;try{const result=await callFunction('tournamentRegistrationFlow',{action:'createRefereeFollowInvite',tournamentId:selectedTournamentId.value,targetRefereeId:referee?._id||'',previewMode});if(!result?.success)throw new Error(result?.message||result?.error||'裁判关注二维码生成失败');inviteQrCode.value=result.data?.qrCodeUrl||'';inviteMode.value=result.data?.claimMode||'';if(!inviteQrCode.value)throw new Error('服务号关注二维码暂不可用');inviteDialog.value=true}catch(error){ElMessage.error(friendlyInviteError(error))}finally{saving.value=false}}
function exportList() { ElMessage.info('导出名单已准备，正式导出将按当前赛事与筛选范围生成') }
onMounted(load)
</script>

